#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void mean_reduce_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int64_t dim0,
    const int64_t dim1,
    const int64_t dim2,
    const int reduction_dim)
{
    using acc_t = float;                     // accumulation in FP32
    int64_t out_idx = blockIdx.x * blockDim.x + threadIdx.x;

    // total number of output elements (product of non‑reduced dims)
    int64_t out_numel = (reduction_dim == 0) ? dim1 * dim2
                    : (reduction_dim == 1) ? dim0 * dim2
                    : dim0 * dim1;

    if (out_idx >= out_numel) return;

    // map linear output index to 3‑D coordinates (excluding reduced dim)
    int64_t i0 = 0, i1 = 0, i2 = 0;
    if (reduction_dim == 0) {          // output dims: [dim1, dim2]
        i1 = out_idx / dim2;
        i2 = out_idx % dim2;
    } else if (reduction_dim == 1) {   // output dims: [dim0, dim2]
        i0 = out_idx / dim2;
        i2 = out_idx % dim2;
    } else {                           // reduction_dim == 2, output dims: [dim0, dim1]
        i0 = out_idx / dim1;
        i1 = out_idx % dim1;
    }

    // accumulate over the reduced dimension
    acc_t sum = 0.0f;
    int64_t red_size = (reduction_dim == 0) ? dim0
                     : (reduction_dim == 1) ? dim1
                     : dim2;

    for (int64_t r = 0; r < red_size; ++r) {
        int64_t in_idx;
        if (reduction_dim == 0) {               // stride = dim1*dim2
            in_idx = r * (dim1 * dim2) + i1 * dim2 + i2;
        } else if (reduction_dim == 1) {        // stride = dim2
            in_idx = i0 * (dim1 * dim2) + r * dim2 + i2;
        } else {                                 // reduction_dim == 2
            in_idx = i0 * (dim1 * dim2) + i1 * dim2 + r;
        }
        sum += static_cast<acc_t>(input[in_idx]);
    }

    acc_t mean = sum / static_cast<acc_t>(red_size);
    output[out_idx] = static_cast<scalar_t>(mean);
}

// --------------------------------------------------------------------
// C++ wrapper that prepares tensors and launches the kernel
// --------------------------------------------------------------------
torch::Tensor mean_reduce_cuda(torch::Tensor input, int64_t reduction_dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(input.dim() == 3, "only 3‑D tensors are supported in this kernel");

    const int64_t dim0 = input.size(0);
    const int64_t dim1 = input.size(1);
    const int64_t dim2 = input.size(2);

    // compute output shape (remove the reduced dimension)
    std::vector<int64_t> out_shape;
    for (int i = 0; i < 3; ++i) {
        if (i != reduction_dim) out_shape.push_back(input.size(i));
    }
    auto output = torch::empty(out_shape, input.options());

    const int threads = 256;
    const int64_t out_numel = output.numel();
    const int blocks = (out_numel + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "mean_reduce_kernel", ([&] {
        mean_reduce_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            dim0, dim1, dim2,
            static_cast<int>(reduction_dim));
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
    return output;
}

// --------------------------------------------------------------------
// PyBind11 registration
// --------------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("mean_reduce_cuda", &mean_reduce_cuda, "Mean reduction over a dimension (CUDA, fp16)");
}
