# Compile the inline extension (the harness supplies the correct C++ standard)
mean_reduce_mod = load_inline(
    name='mean_reduce_ext',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['mean_reduce_cuda'],
    verbose=False,
)

