        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure proper device / dtype (the reference uses fp16 on GPU)
        if not x.is_cuda:
            raise RuntimeError("ModelNew expects a CUDA tensor")
        if x.dtype != torch.float16:
            raise RuntimeError("ModelNew expects a fp16 tensor")
